<?php session_start(); require 'conectare.php'; $id=filter_input(INPUT_GET,'id_carte',FILTER_VALIDATE_INT) ?: 0; $s=$pdo->prepare('SELECT c.id_carte,c.titlu,c.descriere,c.pret,a.nume_autor FROM carti c JOIN autori a ON a.id_autor=c.id_autor WHERE c.id_carte=?'); $s->execute([$id]); $book=$s->fetch(); if(!$book){http_response_code(404);exit('Carte inexistenta.');} $s=$pdo->prepare('SELECT nume_utilizator,adresa_email,comentariu FROM comentarii WHERE id_carte=? ORDER BY id_comentariu DESC');$s->execute([$id]);$comments=$s->fetchAll(); include 'page_top.php'; include 'meniu.php'; $img="./coperti/$id.jpg"; ?>
